attempts.sql:
SELECT AVG(o_count) FROM (
  SELECT m.molecule_id,
         COALESCE(SUM(CASE WHEN LOWER(a.element) = 'o' THEN 1 ELSE 0 END), 0) AS o_count
  FROM molecule m
  LEFT JOIN atom a ON a.molecule_id = m.molecule_id
  WHERE NOT EXISTS (
    SELECT 1 FROM bond b WHERE b.molecule_id = m.molecule_id AND b.bond_type <> '-'
  )
  GROUP BY m.molecule_id
) t;

